54	#include <stdio.h>
55	#include <stdlib.h>
56	#include <string.h>
57	#include <stdint.h>
58	#include <time.h>
59	#include <wmmintrin.h>
60	
61	static unsigned char SBOX[256];
62	static unsigned char RCON[11];
63	
64	static uint8_t gmul(uint8_t a, uint8_t b) {
65	    uint8_t p = 0;
66	    while (b) {
67	        if (b & 1) p ^= a;
68	        uint8_t hi = a & 0x80;
69	        a = (uint8_t)(a << 1);
70	        if (hi) a ^= 0x1b;
71	        b >>= 1;
72	    }
73	    return p;
74	}
75	
76	static void init_tables(void) {
77	    for (int x = 0; x < 256; x++) {
78	        uint8_t inv = 0;
79	        if (x) {
80	            for (int y = 1; y < 256; y++) {
81	                if (gmul((uint8_t)x, (uint8_t)y) == 1) { inv = (uint8_t)y; break; }
82	            }
83	        }
84	        uint8_t r = (uint8_t)(0x63 ^ inv), t = inv;
85	        for (int i = 0; i < 4; i++) {
86	            t = (uint8_t)((t << 1) | (t >> 7));
87	            r ^= t;
88	        }
89	        SBOX[x] = r;
90	    }
91	    uint8_t rc = 1;
92	    for (int i = 1; i <= 10; i++) { RCON[i] = rc; rc = gmul(rc, 2); }
93	}
94	
95	static void expand_key128(const unsigned char key[16], unsigned char w[176]) {
96	    memcpy(w, key, 16);
97	    int rci = 1;
98	    for (int i = 16; i < 176; i += 4) {
99	        unsigned char t0 = w[i-4], t1 = w[i-3], t2 = w[i-2], t3 = w[i-1];
100	        if (i % 16 == 0) {
101	            unsigned char first = t0;
102	            t0 = (unsigned char)(SBOX[t1] ^ RCON[rci++]);
103	            t1 = SBOX[t2]; t2 = SBOX[t3]; t3 = SBOX[first];
104	        }
105	        w[i]   = (unsigned char)(w[i-16] ^ t0);
106	        w[i+1] = (unsigned char)(w[i-15] ^ t1);
107	        w[i+2] = (unsigned char)(w[i-14] ^ t2);
108	        w[i+3] = (unsigned char)(w[i-13] ^ t3);
109	    }
110	}
111	
112	typedef struct { __m128i rk[11]; unsigned char bytes[176]; } aes128_key;
113	
114	static void key_init(aes128_key *k, const unsigned char key[16]) {
115	    expand_key128(key, k->bytes);
116	    for (int i = 0; i < 11; i++)
117	        k->rk[i] = _mm_loadu_si128((const __m128i *)(k->bytes + 16 * i));
118	}
119	
120	static inline __m128i aes128_encrypt(__m128i b, const aes128_key *k) {
121	    b = _mm_xor_si128(b, k->rk[0]);
122	    for (int r = 1; r <= 9; r++) b = _mm_aesenc_si128(b, k->rk[r]);
123	    return _mm_aesenclast_si128(b, k->rk[10]);
124	}
125	
126	static double now_sec(void) {
127	    struct timespec ts;
128	    clock_gettime(CLOCK_MONOTONIC, &ts);
129	    return (double)ts.tv_sec + 1e-9 * (double)ts.tv_nsec;
130	}
131	
132	static int hexval(char c) {
133	    if (c >= '0' && c <= '9') return c - '0';
134	    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
135	    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
136	    return -1;
137	}
138	
139	static void hex2bytes(const char *h, unsigned char *out, int n) {
140	    for (int i = 0; i < n; i++) out[i] = (unsigned char)((hexval(h[2*i]) << 4) | hexval(h[2*i+1]));
141	}
142	
143	int main(int argc, char **argv) {
144	    init_tables();
145	
146	    if (argc >= 2 && strcmp(argv[1], "selftest") == 0) {
147	        unsigned char key[16], pt[16], ct[16];
148	        for (int i = 0; i < 16; i++) { key[i] = (unsigned char)i; pt[i] = (unsigned char)(0x10 + i); }
149	        aes128_key k; key_init(&k, key);
150	        __m128i b = _mm_loadu_si128((const __m128i *)pt);
151	        b = aes128_encrypt(b, &k);
152	        _mm_storeu_si128((__m128i *)ct, b);
153	        printf("SELFTEST key=");
154	        for (int i = 0; i < 16; i++) printf("%02x", key[i]);
155	        printf(" pt=");
156	        for (int i = 0; i < 16; i++) printf("%02x", pt[i]);
157	        printf(" ct=");
158	        for (int i = 0; i < 16; i++) printf("%02x", ct[i]);
159	        printf("\n");
160	        return 0;
161	    }
162	
163	    if (argc >= 2 && strcmp(argv[1], "vec") == 0) {
164	        char line[256];
165	        while (fgets(line, sizeof line, stdin)) {
166	            char kh[64], ph[64];
167	            if (sscanf(line, "%63s %63s", kh, ph) != 2) continue;
168	            unsigned char key[16], pt[16], ct[16];
169	            hex2bytes(kh, key, 16); hex2bytes(ph, pt, 16);
170	            aes128_key k; key_init(&k, key);
171	            __m128i b = _mm_loadu_si128((const __m128i *)pt);
172	            b = aes128_encrypt(b, &k);
173	            _mm_storeu_si128((__m128i *)ct, b);
174	            printf("VEC ct=");
175	            for (int i = 0; i < 16; i++) printf("%02x", ct[i]);
176	            printf("\n");
177	            fflush(stdout);
178	        }
179	        return 0;
180	    }
181	
182	    if (argc >= 5 && strcmp(argv[1], "bench") == 0) {
183	        const char *mode = argv[2];
184	        uint64_t N = strtoull(argv[3], NULL, 10);
185	        int reps = atoi(argv[4]);
186	        unsigned char key[16], pt[16];
187	        for (int i = 0; i < 16; i++) { key[i] = (unsigned char)i; pt[i] = (unsigned char)(0x10 + i); }
188	        aes128_key k;
189	
190	        if (strcmp(mode, "fresh") == 0) {
191	            for (int rep = 1; rep <= reps; rep++) {
192	                uint64_t acc = 0;
193	                double t0 = now_sec();
194	                for (uint64_t i = 0; i < N; i++) {
195	                    unsigned char kk[16]; memcpy(kk, key, 16);
196	                    kk[0] = (unsigned char)(i & 0xff);
197	                    kk[1] = (unsigned char)((i >> 8) & 0xff);
198	                    kk[2] = (unsigned char)((i >> 16) & 0xff);
199	                    key_init(&k, kk);
200	                    __m128i b = _mm_set1_epi64x((long long)i);
201	                    b = aes128_encrypt(b, &k);
202	                    acc ^= (uint64_t)_mm_cvtsi128_si64(b) ^ (uint64_t)_mm_extract_epi64(b, 1);
203	                }
204	                double el = now_sec() - t0;
205	                printf("RESULT mode=fresh N=%llu rep=%d elapsed_s=%.6f rate=%.6e acc=%llx\n",
206	                       (unsigned long long)N, rep, el, (double)N / el, (unsigned long long)acc);
207	                fflush(stdout);
208	            }
209	        } else if (strcmp(mode, "dep") == 0) {
210	            key_init(&k, key);
211	            for (int rep = 1; rep <= reps; rep++) {
212	                uint64_t acc = 0;
213	                __m128i b = _mm_loadu_si128((const __m128i *)pt);
214	                double t0 = now_sec();
215	                for (uint64_t i = 0; i < N; i++) {
216	                    b = aes128_encrypt(b, &k);
217	                    acc ^= (uint64_t)_mm_cvtsi128_si64(b) ^ (uint64_t)_mm_extract_epi64(b, 1);
218	                }
219	                double el = now_sec() - t0;
220	                printf("RESULT mode=dep N=%llu rep=%d elapsed_s=%.6f rate=%.6e acc=%llx\n",
221	                       (unsigned long long)N, rep, el, (double)N / el, (unsigned long long)acc);
222	                fflush(stdout);
223	            }
224	        } else if (strcmp(mode, "ind") == 0) {
225	            key_init(&k, key);
226	            for (int rep = 1; rep <= reps; rep++) {
227	                uint64_t acc = 0;
228	                double t0 = now_sec();
229	                for (uint64_t i = 0; i < N; i++) {
230	                    __m128i b = _mm_xor_si128(_mm_set1_epi64x((long long)i),
231	                                              _mm_set1_epi64x((long long)(i ^ 0x5555555555555555ULL)));
232	                    b = aes128_encrypt(b, &k);
233	                    acc ^= (uint64_t)_mm_cvtsi128_si64(b) ^ (uint64_t)_mm_extract_epi64(b, 1);
234	                }
235	                double el = now_sec() - t0;
236	                printf("RESULT mode=ind N=%llu rep=%d elapsed_s=%.6f rate=%.6e acc=%llx\n",
237	                       (unsigned long long)N, rep, el, (double)N / el, (unsigned long long)acc);
238	                fflush(stdout);
239	            }
240	        } else {
241	            fprintf(stderr, "unknown bench mode: %s\n", mode);
242	            return 2;
243	        }
244	        return 0;
245	    }
246	
247	    fprintf(stderr, "usage: %s selftest | vec | bench <fresh|dep|ind> <N> <reps>\n", argv[0]);
248	    return 2;
249	}
